-- ================================================================
-- CIVICBRAIN STEP 13 - LOAD VALIDATED CLUSTER DATA
-- Generated from validated CSV outputs.
-- Existing production tables are not modified.
-- ================================================================

BEGIN;

TRUNCATE TABLE
    step13_cluster_complaint,
    step13_clusters
RESTART IDENTITY;



COMMIT;

-- ================================================================
-- VERIFICATION
-- ================================================================
SELECT COUNT(*) AS cluster_count FROM step13_clusters;

SELECT COUNT(*) AS cluster_member_count FROM step13_cluster_complaint;

SELECT c.serviceability_status, COUNT(*) AS cluster_count FROM step13_clusters c GROUP BY c.serviceability_status ORDER BY c.serviceability_status;

SELECT c.work_type, COUNT(*) AS cluster_count, SUM(c.complaint_count) AS job_count FROM step13_clusters c GROUP BY c.work_type ORDER BY c.work_type;